import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { cn } from "@/lib/utils";

export type PopoverVariant = "default" | "form" | "menu" | "rich";

export const Popover = PopoverPrimitive.Root;
export const PopoverTrigger = PopoverPrimitive.Trigger;
export const PopoverAnchor = PopoverPrimitive.Anchor;
export const PopoverClose = PopoverPrimitive.Close;

export interface PopoverContentProps
  extends React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content> {
  variant?: PopoverVariant;
  /** Width preset — menu stays compact, form/rich expand. */
  width?: "auto" | "sm" | "md" | "lg";
}

const variantClasses: Record<PopoverVariant, string> = {
  default: "p-4",
  form: "p-0",
  menu: "p-1.5",
  rich: "p-0 overflow-hidden",
};

const widthClasses: Record<NonNullable<PopoverContentProps["width"]>, string> = {
  auto: "w-auto min-w-[12rem]",
  sm: "w-[14rem]",
  md: "w-[18rem]",
  lg: "w-[22rem]",
};

const popoverSurfaceClass =
  "border border-[#ded3c5] bg-[#f7f2e9] text-[#181716] " +
  "[box-shadow:0_26px_72px_-34px_rgba(0,0,0,.78),0_12px_34px_-20px_rgba(18,16,13,.46),0_1px_2px_rgba(18,16,13,.10)]";

const popoverTokenClass =
  "[--background:#fffaf2] [--foreground:#181716] [--muted-foreground:#655d52] [--border:#d8cab8] [--surface:#fffaf2]";

export function PopoverContent({
  className,
  variant = "default",
  width = "auto",
  align = "center",
  sideOffset = 6,
  collisionPadding = 12,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "z-[120] origin-[var(--radix-popover-content-transform-origin)] transform-gpu outline-none",
          popoverSurfaceClass,
          popoverTokenClass,
          "rounded-[18px]",
          "data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          "data-[state=open]:data-[side=bottom]:slide-in-from-top-2 data-[state=open]:data-[side=top]:slide-in-from-bottom-2",
          "data-[state=open]:data-[side=left]:slide-in-from-right-2 data-[state=open]:data-[side=right]:slide-in-from-left-2",
          "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          "data-[state=open]:duration-180 data-[state=closed]:duration-120",
          "data-[state=open]:ease-[cubic-bezier(0.23,1,0.32,1)] data-[state=closed]:ease-[cubic-bezier(0.23,1,0.32,1)]",
          "motion-reduce:animate-none",
          widthClasses[width],
          variantClasses[variant],
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  );
}

export function PopoverHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "border-b border-[#e4dbcf] px-4 py-3",
        className,
      )}
      {...props}
    />
  );
}

export function PopoverBody({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn("px-4 py-3", className)} {...props} />;
}

export function PopoverTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn(
        "text-sm font-semibold tracking-[-0.01em] text-[#181716]",
        className,
      )}
      {...props}
    />
  );
}

export function PopoverDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn(
        "mt-1 text-[12px] leading-[1.5] text-[#655d52]",
        className,
      )}
      {...props}
    />
  );
}

export interface PopoverMenuItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  inset?: boolean;
  destructive?: boolean;
}

export function PopoverMenuItem({
  className,
  inset,
  destructive,
  ...props
}: PopoverMenuItemProps) {
  return (
    <button
      type="button"
      className={cn(
        "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-[13px]",
        "text-[#24211d] transition-[background-color,color] duration-140 ease-[cubic-bezier(0.23,1,0.32,1)]",
        "hover:bg-[#ede5da]",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#b9aa98]",
        inset && "pl-8",
        destructive && "text-[#b42318] hover:bg-[#f2ded8]",
        className,
      )}
      {...props}
    />
  );
}

export function PopoverMenuSeparator({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      role="separator"
      className={cn("my-1 h-px bg-[#e4dbcf]", className)}
      {...props}
    />
  );
}

export interface PopoverRichMediaProps extends React.HTMLAttributes<HTMLDivElement> {
  src: string;
  alt: string;
}

export function PopoverRichMedia({ src, alt, className, ...props }: PopoverRichMediaProps) {
  return (
    <div className={cn("relative aspect-[16/10] w-full overflow-hidden", className)} {...props}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={alt}
        className="size-full object-cover"
      />
      <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(to_top,rgba(0,0,0,0.55)_0%,transparent_55%)]" />
    </div>
  );
}
